// ============================================================================
// SPDM_apb: APB4 register wrapper around SPDM_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/SPDM.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/SPDM.md
// ============================================================================
module SPDM_apb #(
  parameter int NM = 4,
  parameter int CC_AW = 14
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic [255:0] sl_seed,
  input logic sl_valid,
  input logic rq_valid,
  input logic [7:0] rq_data,
  input logic rq_last,
  output logic rq_ready,
  output logic rs_valid,
  output logic [7:0] rs_data,
  output logic rs_last,
  input logic rs_ready
);
  localparam logic [31:0] ID_VALUE = 32'h53640100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [24:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd25) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [7:0]    c_ct_exp;
  logic [31:0]   c_asym_id;
  logic [1:0]    c_pset;
  logic [14:0]   c_cc_len;
  logic [3:0]    c_m_en;
  logic [3:0]    c_m_tcb;
  logic [31:0]   c_m_type;
  logic          c_st_we;
  logic          c_st_sel;
  logic [11:0]   c_st_addr;
  logic [31:0]   c_st_data;
  logic          c_kg_start;
  logic          c_kg_sel;
  logic [255:0]  c_seed;
  logic          c_pk_open;
  logic          c_clr;
  logic          c_pk_valid;
  logic [31:0]   c_pk_data;
  logic          c_pk_last;
  logic          c_pk_ready;
  logic          c_rn_valid;
  logic [31:0]   c_rn_data;
  logic          c_rn_ready;
  logic          c_busy;
  logic [1:0]    c_conn;
  logic          c_key_ok;
  logic [1:0]    c_key_pset;
  logic          c_rsp_done;
  logic          c_rsp_err;
  logic [7:0]    c_err_code;
  logic          c_kg_done;
  logic          c_cmd_err;
  SPDM_top #(.NM(NM), .CC_AW(CC_AW)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .ct_exp(c_ct_exp),
    .asym_id(c_asym_id),
    .pset(c_pset),
    .cc_len(c_cc_len),
    .m_en(c_m_en),
    .m_tcb(c_m_tcb),
    .m_type(c_m_type),
    .st_we(c_st_we),
    .st_sel(c_st_sel),
    .st_addr(c_st_addr),
    .st_data(c_st_data),
    .kg_start(c_kg_start),
    .kg_sel(c_kg_sel),
    .seed(c_seed),
    .sl_seed(sl_seed),
    .sl_valid(sl_valid),
    .pk_open(c_pk_open),
    .clr(c_clr),
    .pk_valid(c_pk_valid),
    .pk_data(c_pk_data),
    .pk_last(c_pk_last),
    .pk_ready(c_pk_ready),
    .rn_valid(c_rn_valid),
    .rn_data(c_rn_data),
    .rn_ready(c_rn_ready),
    .rq_valid(rq_valid),
    .rq_data(rq_data),
    .rq_last(rq_last),
    .rq_ready(rq_ready),
    .rs_valid(rs_valid),
    .rs_data(rs_data),
    .rs_last(rs_last),
    .rs_ready(rs_ready),
    .busy(c_busy),
    .conn(c_conn),
    .key_ok(c_key_ok),
    .key_pset(c_key_pset),
    .rsp_done(c_rsp_done),
    .rsp_err(c_rsp_err),
    .err_code(c_err_code),
    .kg_done(c_kg_done),
    .cmd_err(c_cmd_err)
  );

  // ---------------- registers ----------------
  logic [6:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [10:0] r_CFG;   // 12'h014 CFG
  logic [31:0] r_ASYM;   // 12'h018 ASYM
  logic [14:0] r_CCLEN;   // 12'h01C CCLEN
  logic [7:0] r_MEAS;   // 12'h020 MEAS
  logic [31:0] r_MTYPE;   // 12'h024 MTYPE
  logic [31:0] h_STORE0;   // 12'h028 STORE0 holding register
  logic [12:0] h_STORE1;   // 12'h02C STORE1 holding register
  logic [31:0] r_SEED0;   // 12'h030 SEED0
  logic [31:0] r_SEED1;   // 12'h034 SEED1
  logic [31:0] r_SEED2;   // 12'h038 SEED2
  logic [31:0] r_SEED3;   // 12'h03C SEED3
  logic [31:0] r_SEED4;   // 12'h040 SEED4
  logic [31:0] r_SEED5;   // 12'h044 SEED5
  logic [31:0] r_SEED6;   // 12'h048 SEED6
  logic [31:0] r_SEED7;   // 12'h04C SEED7
  logic [2:0] p_CMD;   // 12'h050 CMD (pulses)
  logic [31:0] h_PK0;   // 12'h054 PK0 holding register
  logic [0:0] h_PK1;   // 12'h058 PK1 holding register
  logic [31:0] h_RN;   // 12'h05C RN holding register
  logic vld_STORE;
  logic avail_PK;
  logic full_RN;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 11'h0;
      r_ASYM <= 32'h0;
      r_CCLEN <= 15'h0;
      r_MEAS <= 8'h0;
      r_MTYPE <= 32'h0;
      h_STORE0 <= '0;
      h_STORE1 <= '0;
      r_SEED0 <= 32'h0;
      r_SEED1 <= 32'h0;
      r_SEED2 <= 32'h0;
      r_SEED3 <= 32'h0;
      r_SEED4 <= 32'h0;
      r_SEED5 <= 32'h0;
      r_SEED6 <= 32'h0;
      r_SEED7 <= 32'h0;
      p_CMD <= '0;
      h_PK0 <= '0;
      h_PK1 <= '0;
      h_RN <= '0;
      vld_STORE <= 1'b0;
      avail_PK <= 1'b0;
      full_RN <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[6:0] & wmask[6:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[6:0]) | (PWDATA[6:0] & wmask[6:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[10:0]) | (PWDATA[10:0] & wmask[10:0]);
      if (wr && hit[6]) r_ASYM <= (r_ASYM & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_CCLEN <= (r_CCLEN & ~wmask[14:0]) | (PWDATA[14:0] & wmask[14:0]);
      if (wr && hit[8]) r_MEAS <= (r_MEAS & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[9]) r_MTYPE <= (r_MTYPE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[12]) r_SEED0 <= (r_SEED0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[13]) r_SEED1 <= (r_SEED1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[14]) r_SEED2 <= (r_SEED2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[15]) r_SEED3 <= (r_SEED3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[16]) r_SEED4 <= (r_SEED4 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[17]) r_SEED5 <= (r_SEED5 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[18]) r_SEED6 <= (r_SEED6 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[19]) r_SEED7 <= (r_SEED7 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      p_CMD <= (wr && hit[20]) ? PWDATA[2:0] & wmask[2:0] : '0;
      if (wr && hit[10]) h_STORE0 <= (h_STORE0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[11]) h_STORE1 <= (h_STORE1 & ~wmask[12:0]) | (PWDATA[12:0] & wmask[12:0]);
      vld_STORE <= wr && hit[11];
      if (c_pk_valid && (!avail_PK || (rd && hit[22]))) begin
        h_PK0[31:0] <= c_pk_data[31:0];
        h_PK1 <= c_pk_last;
        avail_PK <= 1'b1;
      end else if (rd && hit[22]) avail_PK <= 1'b0;
      if (wr && hit[23] && !full_RN) h_RN <= (h_RN & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[23] && !full_RN) full_RN <= 1'b1;
      else if (full_RN && c_rn_ready) full_RN <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_ct_exp = r_CFG[7:0];
  assign c_pset = r_CFG[9:8];
  assign c_kg_sel = r_CFG[10:10];
  assign c_asym_id = r_ASYM[31:0];
  assign c_cc_len = r_CCLEN[14:0];
  assign c_m_en = r_MEAS[3:0];
  assign c_m_tcb = r_MEAS[7:4];
  assign c_m_type = r_MTYPE[31:0];
  assign c_st_data[31:0] = h_STORE0[31:0];
  assign c_st_addr[11:0] = h_STORE1[11:0];
  assign c_st_sel = h_STORE1[12:12];
  assign c_seed[31:0] = r_SEED0[31:0];
  assign c_seed[63:32] = r_SEED1[31:0];
  assign c_seed[95:64] = r_SEED2[31:0];
  assign c_seed[127:96] = r_SEED3[31:0];
  assign c_seed[159:128] = r_SEED4[31:0];
  assign c_seed[191:160] = r_SEED5[31:0];
  assign c_seed[223:192] = r_SEED6[31:0];
  assign c_seed[255:224] = r_SEED7[31:0];
  assign c_kg_start = p_CMD[0:0];
  assign c_pk_open = p_CMD[1:1];
  assign c_clr = p_CMD[2:2];
  assign c_rn_data[31:0] = h_RN[31:0];
  assign c_st_we = vld_STORE;
  assign c_pk_ready = ~avail_PK | (rd & hit[22]);
  assign c_rn_valid = full_RN;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_rsp_done;
    irq_set[1] = c_rsp_err;
    irq_set[2] = c_kg_done;
    irq_set[3] = c_cmd_err;
    irq_set[4] = c_pk_valid & (~avail_PK | (rd & hit[22]));
    irq_set[5] = full_RN & c_rn_ready;
    irq_set[6] = wr & (hit[23]) & full_RN;
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {full_RN, avail_PK};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CFG);
      10'd6: apb_rdata = 32'(r_ASYM);
      10'd7: apb_rdata = 32'(r_CCLEN);
      10'd8: apb_rdata = 32'(r_MEAS);
      10'd9: apb_rdata = 32'(r_MTYPE);
      10'd10: apb_rdata = 32'(h_STORE0);
      10'd11: apb_rdata = 32'(h_STORE1);
      10'd21: apb_rdata = 32'(h_PK0);
      10'd22: apb_rdata = 32'(h_PK1);
      10'd23: apb_rdata = 32'(h_RN);
      10'd24: apb_rdata = 32'({c_err_code, c_key_pset, c_key_ok, c_conn, c_busy});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
